1267	\begin{lemma}[Direct sums of conditionally linear functions]\label{lem:cl-func-prod}
1268		\lean{MIPStarRE.QPBT.IsCondLinear.directSum}
1269		\leanok
1270		\uses{def:cl-func, def:register-subspace}
1271		Let $m \ge 1$ be an integer and let $V^{(1)}, V^{(2)}, \dots, V^{(m)}$ be register subspaces of $V$ such that $V = \bigoplus_{j=1}^m V^{(j)}$. Suppose that, for each $j \in \{1, 2, \dots, m\}$, $L^{(j)}$ is an $\ell_j$-level conditionally linear function on $V^{(j)}$. Then the direct sum $L = \bigoplus_{j=1}^m L^{(j)}$, defined by
1272		\[
1273			L(x) = \sum_{j=1}^m L^{(j)}(x^{(j)})
1274		\]
1275		for all $x = \sum_{j=1}^m x^{(j)} \in \bigoplus_{j=1}^m V^{(j)}$, is an $\ell$-level CL function on $V$ for $\ell = \max_j \{\ell_j\}$; the maximum exists since $m \ge 1$.
1276		With zero-based indices, the summand labelled $r\in\{0,\ldots,m-1\}$
1277		corresponds to the paper's summand $j=r+1$.
1278	\end{lemma}
1279	\begin{proof}
1280		\leanok
1281		\uses{def:cl-func, lem:cl-func-prod-same-level}
1282		Since an $\ell$-level CL function is also $k$-level conditionally linear for all $k \ge \ell$, it suffices to prove the claim when $\ell_j = \ell$ for all $j$. Proceed by induction on $\ell$. For $\ell = 0$ every $L^{(j)}$ is the zero function on $V^{(j)}$, so $L$ is the zero function on $V$, which is the unique $0$-level CL function on $V$ (Definition~\ref{def:cl-func}). For the inductive step with $\ell \ge 1$, decompose each $L^{(j)}$ into its first-level linear part $L^{(j)}_1$ on $V^{(j)}_1$ and its family of $(\ell-1)$-level remainders $L^{(j)}_{>1,\,v_j}$ on $V^{(j)}_{>1}$. The direct sums of the first-level parts define a linear map on $V_1 = \bigoplus_j V^{(j)}_1$, and, for each prefix value $v = \sum_j v_j$, the direct sums of the remainders are $(\ell-1)$-level conditionally linear on $V_{>1} = \bigoplus_j V^{(j)}_{>1}$ by the induction hypothesis. This exhibits $L$ in the form required by Definition~\ref{def:cl-func}.
1283	\end{proof}
