402		\begin{enumerate}
403			\item for $W \in \{X,Z\}$, $L_{(\mathsf{Point},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{Point}}(u_W,s,v)$, a $1$-level CL function, where the range $V_W \oplus V_I \oplus V_V$ of $L_{\mathsf{Point}}$ is embedded in $V^{\mathrm{pauli}}$ in the natural way (the same convention applies in items~2 and~3);
404			\item for $W \in \{X,Z\}$, $L_{(\mathsf{ALine},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{ALine}}(u_W,s,v)$, a $2$-level CL function;
405			\item for $W \in \{X,Z\}$, $L_{(\mathsf{DLine},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{DLine}}(u_W,s,v)$, a $3$-level CL function;
406			\item for $t \in \mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$, $L_t(u_X,u_Z,s,v,r_X,r_Z) = (u_X,u_Z,0,0,r_X,r_Z)$, the $1$-level CL function projecting onto $V_X \oplus V_Z \oplus V_{R_X} \oplus V_{R_Z}$;
