474		Fix an admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}) and let $M = 2^m$. Answers in the game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ take the following forms, depending on the question type; answers not of the prescribed form are rejected.
475		% The paper's format table writes the line contents loosely as (u_W, s) and (u_W, s, v);
476		% by the sampling procedure the actual contents are the canonical pairs (u_0, s) and
477		% triples (u_0, s, v') with v' = pi_{i-1}(v). We state the canonical form.
478		\begin{itemize}
479			\item $(\mathsf{Point},W)$: content $y \in \F_q^m$; answer an element of $\F_q$.
480			\item $(\mathsf{ALine},W)$: content $(u_0, s) \in \F_q^m \times \F_q$; answer a univariate polynomial $f\colon \F_q \to \F_q$ of degree at most $d$.
481			\item $(\mathsf{DLine},W)$: content $(u_0, s, v') \in \F_q^m \times \F_q \times \F_q^m$; answer a univariate polynomial $f\colon \F_q \to \F_q$ of degree at most $md$.
482			\item $\mathsf{Pair}$: content $\omega = (u_X, u_Z, r_X, r_Z) \in (\F_q^m)^2 \times \F_q^2$; answer $(\beta_X, \beta_Z) \in \F_2^2$.
483			\item $(\mathsf{Pair},W)$: content $\omega$ as above; answer an element of $\F_2$.
484			\item $\mathsf{Constraint}_i$: content $\omega$ as above; answer $(\alpha_{v_1}, \alpha_{v_2}, \alpha_{v_3}) \in \F_2^3$, indexed by the variable indices $(v_1,v_2,v_3)$ of $\mathsf{Constraint}_i$.
485			\item $\mathsf{Variable}_j$: content $\omega$ as above; answer an element of $\F_2$.
486			\item $(\mathsf{Pauli},W)$: content $0$; answer an element of $\F_q^M$.
487		\end{itemize}
488		The win predicate $D^{\mathrm{pauli}} = D^{\mathrm{pauli}}_{\mathsf{qldparams}}$ is the function of the tuple $(t_{\mathrm A}, x_{\mathrm A}, t_{\mathrm B}, x_{\mathrm B}, a_{\mathrm A}, a_{\mathrm B})$ determined by the following clauses, evaluated for $w \in \{\mathrm A, \mathrm B\}$ and $W \in \{X,Z\}$; in all cases where no action is indicated, the predicate accepts. In the last four clauses, the content of the player whose type lies in $\mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$ is a tuple $(u_X, u_Z, r_X, r_Z)$, from which the predicate first computes
489		\begin{equation}
490			\label{eq:gamma-value}
491			\gamma = \tr\bigl( (\mathrm{ind}_m(u_X) \cdot r_X) \cdot (\mathrm{ind}_m(u_Z) \cdot r_Z) \bigr) \in \F_2\;,
492		\end{equation}
493		where $\mathrm{ind}_m(\cdot) \in \F_q^M$ is the indicator vector of the low-degree encoding (Chapter~\ref{chap:qpbt-algebra}), the inner dot denotes the dot product on $\F_q^M$, and $\tr\colon \F_q \to \F_2$ is the finite-field trace.
494		\begin{enumerate}
495			\item (\textbf{Consistency check}) If $t_{\mathrm A} = t_{\mathrm B}$, accept if and only if $a_{\mathrm A} = a_{\mathrm B}$.
496			\item (\textbf{Low-degree check}) Let $\mathsf{ldparams} = (q,m,d,1)$; admissibility of $\mathsf{qldparams}$ gives $d \ge 1$ and $m \mid q$, so this is a parameter tuple as in Definition~\ref{def:ld-game}.
497			\begin{enumerate}
498				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{ALine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{ALine}, x_{\overline w}, a_w, a_{\overline w})$.
499				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{DLine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{DLine}, x_{\overline w}, a_w, a_{\overline w})$.
500			\end{enumerate}
501			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pauli},W)$, accept if $g_{a_{\overline w}}(x_w) = a_w$, where $g_{a_{\overline w}}$ is the low-degree encoding of $a_{\overline w} \in \F_q^M$ (Chapter~\ref{chap:qpbt-algebra}).
502			\item (\textbf{Commutation check}) If $t_w = (\mathsf{Pair},W)$ and $t_{\overline w} = \mathsf{Pair}$, accept if $a_w = \beta_W$ or $\gamma \neq 0$.
503			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pair},W)$, accept if $\tr(a_w r_W) = a_{\overline w}$ or $\gamma \neq 0$.
504			\item (\textbf{Magic Square check}) If $t_w = \mathsf{Constraint}_i$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $a_w$ satisfies the equation of $\mathsf{Constraint}_i$ and $\alpha_j = a_{\overline w}$.
505			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $j = 1$, $W = X$, and $\tr(a_w r_X) = a_{\overline w}$, or if $j = 5$, $W = Z$, and $\tr(a_w r_Z) = a_{\overline w}$.
506		\end{enumerate}
507		The game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ is the typed game with type set $\mathcal T^{\mathrm{pauli}}$, the question distribution of Definition~\ref{def:pauli-question-distribution}, and win predicate $D^{\mathrm{pauli}}_{\mathsf{qldparams}}$.
508	\end{definition}
